"""Build a browser-local workbench with the registered repository BINs."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def build(shell,write,catalog):
    for image in catalog['images']:
        write('tools/bins/'+image['id']+'.bin',(ROOT/image['file']).read_bytes())
    report=json.loads((ROOT/'analysis/firmware/decode_catalog.json').read_text(encoding='utf-8'))
    for image in report['images']:
        maps=json.loads((ROOT/image['maps_path']).read_text(encoding='utf-8'))
        keys=('id','display_name','data_address','end_exclusive','rows','columns','element_bytes','byte_order','kind','row_axis','column_axis','input_min_raw','index_divisor','index_factor_raw','category','confidence','physical_role','units','inputs','engineering_decode')
        write('tools/maps/'+image['id']+'.json',json.dumps([{k:m[k] for k in keys if k in m} for m in maps],ensure_ascii=False)+'\n')
    body='''<div class="page-heading"><div class="kicker">XT660 / WORKBENCH</div><h1>Read. Tune. Flash.</h1><p>Your ECU workflow, from backup to verified readback. BIN editing is available now; live ECU operations are in development. Files stay in your browser.</p></div>
<nav class="tool-links" aria-label="ECU workflow"><a href="#connect"><span>01</span> Connect</a><a href="#backup"><span>02</span> Read &amp; verify</a><a href="#tune"><span>03</span> Edit &amp; save</a><a href="#flash"><span>04</span> Flash &amp; verify</a></nav>
<p id="tool-error" class="notice" role="alert" hidden></p>
<section id="connect" class="tool-panel"><div class="tool-step">01 / CONNECT</div><h2>Connect your ECU</h2>
<p id="connection-availability">The live ECU connection is in development. Boot connection, reading and flashing are not available in this version.</p><p class="tool-note">XT boot profile · 9,600 baud · applied automatically when live connection is available.</p>
<button id="ecu-connect" disabled aria-describedby="connection-availability">Connect ECU</button>
</section>
<section id="backup" class="tool-panel"><div class="tool-step">02 / READ &amp; VERIFY</div><h2>Read &amp; verify your backup</h2><p>ECU reading is in development. Open an existing BIN below to inspect, compare and edit it now.</p><button id="read-ecu" disabled aria-describedby="connection-availability">Read BIN from ECU</button><h3>Open an existing BIN</h3><p>Choose a BIN already in the repository or open your own file. Each registered BIN loads its own maps. Originals stay unchanged; edits are exported as a separate draft.</p><label>Repository BIN<select id="repo-bin" disabled><option>Loading repository BINs…</option></select></label><button id="repo-open" disabled>Open repository BIN</button><p class="tool-note">Original and modified variants are listed separately. The downloaded bytes are checked against the catalogue’s SHA-256 before opening.</p><label class="file-label">Or open a local BIN<input id="bin-file" type="file" accept=".bin,application/octet-stream"></label><p id="bin-status" role="status">No BIN opened.</p><dl id="bin-facts" class="firmware-facts"></dl>
<div class="tool-actions"><button id="backup-save" disabled>Save untouched BIN</button><button id="backup-report" disabled>Save identity report</button></div>
<label class="file-label">Compare another read<input id="compare-file" type="file" disabled></label><p id="compare-status" role="status"></p></section>
<section id="tune" class="tool-panel"><div class="tool-step">03 / EDIT &amp; SAVE</div><h2>Edit features &amp; maps.</h2><p>The loaded BIN determines the available edits, independently of the bike selector. Registered BINs and copies containing only recognised map or feature changes can be edited. Other modified files remain inspection-only. Map values are raw integers; physical scaling is unfinished.</p>
<div class="checksum-panel"><strong>Automatic startup checksum</strong><p id="checksum-status" role="status" data-status="unverified">No BIN checked.</p><p id="checksum-detail">Checked on open, corrected in the editable copy after every change, and verified again before saving. Originals stay unchanged.</p><a href="../docs/firmware/FLASH_TOOLING.html">Checksum scope and evidence ↗</a></div>
<div class="feature-panel"><h3>Features</h3><p>Choose Enabled or Disabled for each feature. Controls are greyed out when unavailable. These are BIN settings, not live ECU readings. Patches are instruction-tested; ECU hardware operation has not been validated.</p><div id="feature-list"></div>
<div class="feature-row"><div class="feature-heading"><strong id="speed-output-label">Speedo output</strong><div class="feature-options" role="radiogroup" aria-labelledby="speed-output-label"><label><input id="speed-enabled" type="radio" name="speed-output" disabled>Enabled</label><label><input id="speed-disabled" type="radio" name="speed-output" disabled>Disabled</label></div></div>
<form id="speed-form"><label>Pulse offset per reply (−20 to +20)<input id="speed-offset" type="number" min="-20" max="20" step="1" value="0" required disabled></label><button id="speed-apply" disabled>Apply pulse offset</button></form><p id="speed-status" role="status">No supported BIN loaded.</p><a href="../docs/firmware/SPEED_OUTPUT.html">Speed output patch &amp; verification ↗</a></div>
<p id="feature-status" role="status"></p><a href="../docs/firmware/FEATURE_PATCHES.html">Patch addresses &amp; test evidence ↗</a></div>
<div class="map-workspace" id="map-workspace">
<header class="map-workspace-title"><div><span class="tool-step">CALIBRATION WORKSPACE</span><h3>Maps &amp; curves</h3></div><div class="map-history"><button id="edit-undo" disabled>Undo</button><button id="edit-redo" disabled>Redo</button><button id="draft-save" disabled>Save edits to BIN</button><button id="xdf-export" disabled>Export XDF</button></div></header>
<div class="map-layout"><aside class="map-library"><label for="map-search">Find a map</label><input id="map-search" type="search" placeholder="Name, address or reference…" disabled><label for="map-category">Category</label><select id="map-category" disabled><option value="">All categories</option></select><label class="map-filter"><input id="map-changed" type="checkbox" disabled>Changed maps only</label><p id="map-count">Load a BIN to begin.</p><div id="map-list" aria-label="Map library"></div><select id="tune-map" hidden disabled><option>Open a registered BIN first</option></select></aside>
<div class="map-editor"><header class="map-editor-heading"><h4 id="map-title">Choose a BIN to start</h4><p id="tune-status" role="status">Your maps will appear here.</p><a id="map-evidence" hidden>Map meaning &amp; evidence ↗</a></header>
<div class="map-toolbar"><label>Display<select id="map-display" disabled><option value="draft">Edited values</option><option value="original">Original values</option><option value="difference">Difference from original</option></select></label><label>Grid size<select id="map-fit" disabled><option value="fit">Fit all columns</option><option value="readable">Larger cells</option></select></label><button id="map-all" disabled>Select all</button><button id="map-row" disabled>Select row</button><button id="map-column" disabled>Select column</button><button id="map-copy" disabled>Copy selection</button></div>
<p class="map-help">Drag or Shift-click to select a block. Arrow keys move; Shift extends. Ctrl/Cmd+C copies and Ctrl/Cmd+V previews a paste.</p>
<p id="cell-info" class="map-selection" role="status">No selection.</p>
<form id="map-operation-form" class="map-operation"><label>Edit selection<select id="map-operation" disabled><option value="set">Set value</option><option value="add">Add / subtract</option><option value="multiply">Multiply</option><option value="horizontal">Interpolate across columns</option><option value="vertical">Interpolate down rows</option><option value="smooth">Smooth selection</option><option value="restore">Restore original</option><option value="paste">Paste a block</option></select></label><label id="map-factor-label">Value<input id="map-factor" type="number" step="any" value="0" disabled></label><button id="ws-preview" disabled>Preview edit</button></form>
<label id="map-paste-label" hidden>Paste tabular values<textarea id="map-paste" rows="3" placeholder="Paste rows from a spreadsheet or another map"></textarea></label>
<div id="map-preview-panel" class="map-preview-panel" hidden><strong id="map-preview-summary"></strong><p>Outlined cells show the proposed values. Apply commits the whole edit as one undo step.</p><button id="map-apply" disabled>Apply edit</button><button id="map-cancel" type="button">Cancel preview</button></div>
<p id="map-message" role="status"></p><div id="tune-grid" class="tune-scroll" aria-label="Calibration grid"></div>
<div class="map-graph-heading"><strong>Shape &amp; comparison</strong><label>View<select id="map-graph-mode" disabled><option value="profile">Selected row · 2D</option><option value="surface">Whole map · 3D</option></select></label><label id="map-angle-label" hidden>Rotation<input id="map-angle" type="range" min="-150" max="150" value="-35"></label></div><canvas id="map-graph" width="1000" height="300" role="img" aria-label="Map graph; numerical values are available in the grid"></canvas><p id="map-graph-key" class="map-help">Blue: edited or preview · grey: original. Graph coordinates use cell positions; raw axis values are shown in the grid.</p>
</div></div></div>
<div class="tool-actions"><button id="edit-reset" disabled>Discard edits</button><button id="draft-report" disabled>Save change report</button></div>
<p id="edit-status" role="status">Saving checks and corrects the startup checksum for supported BINs. It does not flash the ECU.</p></section>
<section id="flash" class="tool-panel"><div class="tool-step">04 / FLASH &amp; VERIFY</div><h2>Flash &amp; verify readback</h2><p>Save your edited BIN first. Flashing and readback verification are in development; saving a file does not write it to the ECU.</p><div class="tool-actions"><button id="flash-ecu" disabled aria-describedby="connection-availability">Flash ECU</button><button id="verify-readback" disabled aria-describedby="connection-availability">Verify ECU readback</button></div><a href="../docs/firmware/FLASH_TOOLING.html">Development progress &amp; protocol research ↗</a></section>'''
    write('tools/index.html',shell('Tools — read, tune and flash',body,'tools/index.html','Tools','<link rel="stylesheet" href="../assets/tools.css"><script type="module" src="../assets/tools.mjs"></script>'))
